using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace GearLab {
 public sealed partial class CADStudioForm {
  readonly Border startCard=new Border();
  void InitializeStartCard(){startCard.HorizontalAlignment=HorizontalAlignment.Left;startCard.VerticalAlignment=VerticalAlignment.Top;startCard.Margin=new Thickness(18,48,0,0);startCard.Padding=new Thickness(16);startCard.CornerRadius=new CornerRadius(8);startCard.Background=new SolidColorBrush(Color.FromArgb(238,249,251,254));startCard.BorderBrush=new SolidColorBrush(Color.FromRgb(208,219,232));startCard.BorderThickness=new Thickness(1);Scene.Root.Children.Add(startCard);UpdateStartCard();}
  void UpdateStartCard(){if(startCard.Parent==null)return;bool any=State!=null&&State.Bodies.Count>0;startCard.Visibility=any||editingSketch!=null||Scene.HasConstruction?System.Windows.Visibility.Collapsed:System.Windows.Visibility.Visible;if(any)return;var panel=new StackPanel{Width=310};int sketches=Document.Features.Count(f=>f.Kind=="sketch"&&!f.Suppressed);int off=Document.Features.Count(f=>f.Kind=="sketch"&&f.Suppressed);panel.Children.Add(new TextBlock{Text=off>0&&sketches==0?"Эскиз выключен":sketches>0?"Эскиз готов — создайте тело":"Начните модель в 3D-сцене",FontSize=17,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text=off>0&&sketches==0?"Подавленный эскиз не создаёт геометрию. Включите его или создайте новый.":sketches>0?"Синий контур — ваш эскиз. Выберите «Выдавливание», чтобы получить объём.":"Сетка, оси и камера уже доступны. Создайте эскиз, готовое тело или откройте STEP.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,10)});Action<string,Action> add=(text,action)=>{var b=new Button{Content=text,Padding=new Thickness(9,7,9,7),Margin=new Thickness(0,3,0,3),HorizontalContentAlignment=HorizontalAlignment.Left};b.Click+=(s,e)=>action();panel.Children.Add(b);};if(off>0&&sketches==0)add("Включить последний эскиз",()=>{selectedFeature=Document.Features.Last(f=>f.Kind=="sketch"&&f.Suppressed).Id;Suppress();});if(sketches>0){add("Выдавить эскиз (E)",()=>Operation("extrude"));add("Редактировать последний эскиз",()=>BeginSketch(Document.Features.Last(f=>f.Kind=="sketch"&&!f.Suppressed)));}else{add("＋ Нарисовать эскиз",()=>BeginSketch(null));add("＋ Создать параллелепипед",()=>Operation("box"));add("Открыть STEP / CAD-проект",Open);add("Открыть готовый пример",()=>Replace(CADDocument.Example(),null));}startCard.Child=panel;}
  void RefreshSketchDisplay(CADDocument doc,CADKernelResult result,int count){Scene.SetConstruction(CADSketchDisplay.Build(doc,result,count));UpdateStartCard();}
 }
}
